// @whimtex-effect Learn/Final Tint
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param color _Tint = #FFFFFF
// @param float _Brightness = 1 [0 .. ~3]


float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){

return float4(color.rgb*_Tint.rgb*_Brightness,color.a*_Tint.a*_Opacity);
}

// @whimtex-effect Learn/Vector Field
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @group(Placement)
// @param point _Center = (0.5, 0.5)
// @param float2 _Scale = (1, 1)
// @param float _Angle = 0 [-180 .. 180]
// @endgroup
// @group(Field; _Mode)
// @param hidden enum _Mode = Turbulence {Turbulence:0, Ring:1, Sphere:2, Flow:3, Packed:4}
// @param float _Seed = 17 [1 .. ~5000]
// @param float _Frequency = 5 [0.2 .. 30]
// @param float2 _Stretch = (1, 1)
// @param float _Warp = 0.7 [0 .. 3]
// @param float _Strength = 1 [0 .. 3]
// @param float _Radius = 0.38 [0.05 .. 0.49]
// @param float _Width = 0.12 [0.005 .. 0.3]
// @param float _Phase = 0 [-10 .. 10]
// @endgroup
// @group(Encoding; _Encoding)
// @param hidden enum _Encoding = ScreenVector {ScreenVector:0, UVOffset:1, PackedRGB:2}
// @param bool _FlipY = false
// @helpbox(Data map. Import as linear data when used for UV distortion or channel sampling.)
// @endgroup

float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){
float2 p=LearnRotate(LayerToLocal(uv)-_Center,-_Angle)/max(abs(_Scale),.001);

float2 q=p*_Frequency/max(abs(_Stretch),.001)+_Phase;
float2 v=0;float z=0;float r=length(p);
if(_Mode<.5 || _Mode>2.5){
 float2 w=float2(LearnNoise(q*.6,_Seed),LearnNoise(q*.6+31,_Seed+11))-.5;
 q+=w*_Warp;
 v=float2(LearnNoise(q,_Seed+71),LearnNoise(q+19,_Seed+137))*2-1;
 v*=_Strength;z=sqrt(saturate(1-dot(v,v)));
}else if(_Mode<1.5){
 float height=exp(-pow((r-_Radius)/max(_Width,.001),2));
 v=p/max(r,.00001)*height*_Strength;z=height;
}else{
 float inside=LearnEdge(r-_Radius,.001);v=p/max(_Radius,.001)*inside*_Strength;
 z=sqrt(saturate(1-dot(v,v)))*inside;
}
v.y*=1-2*_FlipY;
float3 encoded=float3(saturate(v*.5+.5),saturate(z));
if(_Encoding>.5)encoded.b=0;
if(_Encoding>1.5)encoded=float3(saturate(v*.8+.5),LearnNoise(q+73,_Seed+451));
// Packed channel values are linear data, not display colors.
return float4(encoded,_Opacity);
}
